class Solution {
public:
    int minElements(vector<int>& nums, int limit, int goal) {
        long long sum = 0;
        for (int x : nums) sum += x;
        long long diff = (long long)goal - sum;
        long long absDiff = diff < 0 ? -diff : diff;
        return (int)((absDiff + limit - 1) / limit);
    }
};
